namespace ghidra.app.util.viewer.field;



using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra.app.util;
using ghidra.app.util.viewer.format;
using ghidra.app.util.viewer.listingpanel;
using ghidra.app.util.viewer.proxy;
using ghidra.app.util.viewer.proxy;
using ghidra.framework.options;
using ghidra.framework.options;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;

/**
 * Generates field to indicate collapsed function for areas of hidden code.
 */
public class CollapsedCodeFieldFactory : FieldFactory {
	public static readonly string FIELD_NAME = "Collapsed Code";

	public CollapsedCodeFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightStringProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	private CollapsedCodeFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {
	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		if (!enabled || !(proxy is CodeUnitProxy cuProxy)) {
			return null;
		}
		CodeUnit cu = cuProxy.getObject();
		Address address = cu.getAddress();
		Function function = cu.getProgram().getListing().getFunctionContaining(address);
		if (function == null) {
			return null;
		}
		string text = "<Collapsed: " + function.getName() + "()>";
		AttributedString s = new AttributedString(text, ListingColors.COLLAPSED_CODE, getMetrics());
		FieldElement element = new TextFieldElement(s, 0, 0);
		return ListingTextField.createSingleLineTextField(this, cuProxy, element, startX + varWidth,
			width, hlProvider);
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		object obj = bf.getProxy().getObject();
		if (obj is CodeUnit cu) {
			Address address = cu.getAddress();
			ListingModel layoutModel = bf.getProxy().getListingLayoutModel();
			Program program = layoutModel.getProgram();
			return new CollapsedCodeLocation(program, address);
		}
		return null;
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation programLoc) {
		if (programLoc is CollapsedCodeLocation) {
			return new FieldLocation(index, fieldNum, 0, 0);
		}
		return null;
	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		// this factory only appears in the header DIVIDER tab (which is called "Address Break" in
		// the gui)
		return category == FieldFormatModel.DIVIDER;
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions displayOptions, ToolOptions fieldOptions) {
		return new CollapsedCodeFieldFactory(formatModel, provider, displayOptions, fieldOptions);
	}
}
